tests:
test({ sr: 'pretvara svojstva u tekstove', en: 'turns properties into texts' }, () => {
  expect(formatEntries({ name: 'Ana', age: 20 })).toEqual(['name: Ana', 'age: 20']);
});
test({ sr: 'zadržava redosled iz objekta', en: 'keeps the order from the object' }, () => {
  expect(formatEntries({ b: 1, a: 2 })).toEqual(['b: 1', 'a: 2']);
});
test({ sr: 'prazan objekat daje prazan niz', en: 'an empty object gives an empty array' }, () => {
  expect(formatEntries({})).toEqual([]);
});

hiddenTests:
test('0 and false are not skipped', () => {
  expect(formatEntries({ count: 0, on: false })).toEqual(['count: 0', 'on: false']);
});
test('true becomes text', () => {
  expect(formatEntries({ active: true })).toEqual(['active: true']);
});
test('an empty text is still a value', () => {
  expect(formatEntries({ note: '' })).toEqual(['note: ']);
});
test('the order is not sorted alphabetically', () => {
  expect(formatEntries({ zebra: 1, apple: 2, mango: 3 })).toEqual(['zebra: 1', 'apple: 2', 'mango: 3']);
});
test('a single property', () => {
  expect(formatEntries({ x: 'y' })).toEqual(['x: y']);
});
test('does not change the object', () => {
  const obj = { a: 1, b: 2 };
  formatEntries(obj);
  expect(obj).toEqual({ a: 1, b: 2 });
});

solutions.code:
function formatEntries(obj) {
  const result = [];
  for (const [key, value] of Object.entries(obj)) {
    result.push(key + ': ' + value);
  }
  return result;
}

function formatEntries(obj) {
  const result = [];
  for (const key of Object.keys(obj)) {
    result.push(key + ': ' + obj[key]);
  }
  return result;
}
